import React from 'react';
import './BookCard.css';
import PrimaryButton from '../../PrimaryButton/PrimaryButton';
import { useNavigate } from 'react-router-dom';
import { useBookContext } from '../../../context/BookContext';

const BookCard = ({ id }) => {
  const navigate = useNavigate();
  const { books } = useBookContext();

  // Знаходимо потрібну книгу за її id
  const book = books.find(book => book.id === id);

  if (!book) {
    return <p>Книга не знайдена</p>;
  }

  const { title, description, image, author, price } = book; // Припускаючи, що книга має властивості author та price
  const handleNavigate = () => {
    navigate(`/book/${id}`);
  };
  
  // Використовуйте імпорт зображень відповідно до вашої структури проекту
  const imagePath = require(`../../../assentds/images/${image}`);

  return (
    <div className="book-card">
      <img src={imagePath} alt={title} className="book-image" />
      <h3>{title}</h3>
      <p><strong>Автор:</strong> {author}</p>
      <p><strong>Опис:</strong> {description}</p>
      <p><strong>Ціна:</strong> {price} грн</p>
      <PrimaryButton label="Дізнатись більше" onClick={handleNavigate} />
    </div>
  );
};

export default BookCard;
